def decode_string(s):
    stack = []
    current_string = ''
    current_num = 0

    for ch in s:
        if ch.isdigit():
            current_num = current_num * 10 + int(ch)
        elif ch == '[':
            stack.append((current_string, current_num))
            current_string = ''
            current_num = 0
        elif ch == ']':
            prev_string, count = stack.pop()
            current_string = prev_string + current_string * count
        else:
            current_string += ch

    return current_string

